title:
// Server Component
async function Page({ id }) {
  const note = await db.notes.get(id);         // 필수 데이터 → 서버에서 await
  const commentsPromise = db.comments.get(note.id); // 낮은 우선순위 → await 안 함

  return (
    <div>
      {note}
      <Suspense fallback={<p>Loading...</p>}>
        <Comments commentsPromise={commentsPromise} />
      </Suspense>
    </div>
  );
}

// Client Component
"use client"
function Comments({ commentsPromise }) {
  const comments = use(commentsPromise); // 여기서 await
  return comments.map(comment => <p>{comment}</p>);
}

